    """
    App readiness probe
    """
    region: str
    """
    Host region of the app
    """
    resources: CloudProjectAiResourcesInput
    """
    App resources
    """
    scaling_strategy: CloudProjectAiAppScalingStrategyInput | None = Field(
        default=None, alias="scalingStrategy"
    )
    """
    App scaling strategy
    """
    unsecure_http: bool | None = Field(default=None, alias="unsecureHttp")
