class CloudProjectAiAppProbe(OVHModel):
    """
    AI Solutions App Probe Object
    """

    failure_threshold: int | None = Field(default=None, alias="failureThreshold")
    """
    Minimum consecutive failures for the probe to be considered failed after having
    succeeded. Defaults to 3. Minimum value is 1.
    """
    initial_delay_seconds: int | None = Field(default=None, alias="initialDelaySeconds")
    """
    Number of seconds after the container has started before liveness probes are
    initiated.
    """
    path: str | None = None
    """
    Path to access to check for readiness
    """
    period_seconds: int | None = Field(default=None, alias="periodSeconds")
    """
    How often (in seconds) to perform the probe. Default to 10 seconds. Minimum value is
    1.
    """
    port: int | None = None
    """
    Port to access to check for readiness
    """
    success_threshold: int | None = Field(default=None, alias="successThreshold")
    """
    Minimum consecutive successes for the probe to be considered successful after having
    failed. Defaults to 1. Must be 1 for liveness and startup. Minimum value is 1.
    """
    timeout_seconds: int | None = Field(default=None, alias="timeoutSeconds")
    """
    Number of seconds after which the probe times out. Defaults to 1 second. Minimum
    value is 1.
    """


