class CloudProjectAiAppScalingAutomaticStrategy(OVHModel):
    """
    AI Solutions App automatic scaling strategy object
    """

    average_usage_target: int | None = Field(default=None, alias="averageUsageTarget")
    """
    The average resource usage threshold that the app upscale or downscale will be
    triggered from, in percent
    """
    cooldown_period_seconds: int | None = Field(
        default=None, alias="cooldownPeriodSeconds"
    )
    """
    Number of seconds to wait before scaling app to 0 whenever there are no more
    HTTP/gRPC requests made to it. Only applies when replicasMin=0
    """
    custom_metrics: CloudProjectAiAppAutomaticScalingStrategyCustomMetrics | None = (
        Field(default=None, alias="customMetrics")
    )
    """
    parameters to scale the AI Deploy App based on a custom metric provided by a
    customer-exposed API
    """
    replicas_max: int = Field(alias="replicasMax")
    """
    Maximum number of replicas
    """
    replicas_min: int | None = Field(default=None, alias="replicasMin")
    """
    Minimum number of replicas
    """
    resource_type: CloudProjectAiAppScalingAutomaticStrategyResourceTypeEnum | None = (
        Field(default=None, alias="resourceType")
    )
    """
    Type of the resource to base the automatic scaling on
    """
    scale_down_stabilization_window_seconds: int | None = Field(
        default=None, alias="scaleDownStabilizationWindowSeconds"
    )
    """
    Number of seconds for which past recommendations should be considered while scaling
    down. Must be greater than or equal to zero and less than or equal to 3600 (one
    hour).
    """
    scale_up_stabilization_window_seconds: int | None = Field(
        default=None, alias="scaleUpStabilizationWindowSeconds"
    )
    """
    Number of seconds for which past recommendations should be considered while scaling
    up. Must be greater than or equal to zero and less than or equal to 3600 (one hour).
    """


